import { Hatchet } from '@hatchet-dev/typescript-sdk';
import * as fs from 'fs';

const hatchet = Hatchet.init();

export const processOrder = hatchet.task({
  name: 'processOrder',
  concurrency: {
    expression: 'input.region',
    maxRuns: 1,
  },
  fn: async (input: { region: string }) => {
    const region = input.region;
    const runId = process.env.ZEALT_RUN_ID || 'default';
    const logFile = `/tmp/orders-${runId}.log`;

    fs.appendFileSync(logFile, `start ${region} ${Date.now()}\n`);
    await new Promise(resolve => setTimeout(resolve, 1500));
    fs.appendFileSync(logFile, `end ${region} ${Date.now()}\n`);

    return { success: true };
  }
});

import { Hatchet } from '@hatchet-dev/typescript-sdk';
import { processOrder } from './task.js';

const hatchet = Hatchet.init();

async function main() {
  const worker = await hatchet.worker('order-worker');
  await worker.registerWorkflow(processOrder);
  worker.start();
  console.log('Worker started');
}

main().catch(console.error);

import * as fs from 'fs';
import { processOrder } from './task.js';

async function main() {
  const runId = process.env.ZEALT_RUN_ID || 'default';
  const logFile = `/tmp/orders-${runId}.log`;

  if (fs.existsSync(logFile)) {
    fs.truncateSync(logFile, 0);
  } else {
    fs.writeFileSync(logFile, '');
  }

  const regions = [
    `US-${runId}`,
    `US-${runId}`,
    `EU-${runId}`,
    `EU-${runId}`
  ];

  console.log(`Starting 4 runs for runId: ${runId}`);

  await Promise.all(regions.map(region => processOrder.run({ region })));

  console.log('All runs completed.');
}

main().catch(console.error);
